import type { ComponentProps } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";

import type { Component } from "solid-js";

import { omit } from "solid-js";

const MessageGroup: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div
      data-slot="message-group"
      class={cn("gap-2 flex min-w-0 flex-col", props.class)}
      {...others}
    />
  );
};

type MessageProps = ComponentProps<"div"> & { align?: "start" | "end" };

const Message: Component<MessageProps> = (props) => {
  const others = omit(props, "class", "align");
  return (
    <div
      data-slot="message"
      data-align={props.align ?? "start"}
      class={cn(
        "gap-2 text-sm group/message relative flex w-full min-w-0 data-[align=end]:flex-row-reverse",
        props.class,
      )}
      {...others}
    />
  );
};

const MessageAvatar: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div
      data-slot="message-avatar"
      class={cn(
        "min-w-8 group-has-data-[slot=message-footer]/message:-translate-y-8 flex w-fit shrink-0 items-center justify-center self-end overflow-hidden rounded-full bg-muted",
        props.class,
      )}
      {...others}
    />
  );
};

const MessageContent: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div
      data-slot="message-content"
      class={cn(
        "gap-2.5 group-data-[align=end]/message:*:data-slot:self-end wrap-break-word flex w-full min-w-0 flex-col",
        props.class,
      )}
      {...others}
    />
  );
};

const MessageHeader: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div
      data-slot="message-header"
      class={cn(
        "px-3 text-xs font-medium text-muted-foreground group-has-data-[variant=ghost]/message:px-0 flex min-w-0 max-w-full items-center",
        props.class,
      )}
      {...others}
    />
  );
};

const MessageFooter: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div
      data-slot="message-footer"
      class={cn(
        "px-3 text-xs font-medium text-muted-foreground group-has-data-[variant=ghost]/message:px-0 flex min-w-0 max-w-full items-center group-data-[align=end]/message:justify-end",
        props.class,
      )}
      {...others}
    />
  );
};

export type { MessageProps };
export {
  Message,
  MessageAvatar,
  MessageContent,
  MessageFooter,
  MessageGroup,
  MessageHeader,
};
